import fs from 'node:fs'; import zlib from 'node:zlib'; import crypto from 'node:crypto'; import * as diff from 'diff';
import { artifactDigest } from './scripts/remediation/board.mjs';
const read=p=>JSON.parse(fs.readFileSync(p,'utf8')), hash=b=>crypto.createHash('sha256').update(b).digest('hex'), unzip=b=>zlib.gunzipSync(Buffer.from(b,'base64')).toString();
const dir='docs/remediation/', a=read(dir+'evidence/W37.07/artifact.json'), b=read(dir+'design/W37.07/baseline-v2.json'), f=read(dir+'evidence/W37.07/source-freeze.json'), w=read(dir+'evidence/W37.07/worker.json'),t=read(dir+'tracker.json').tasks.find(x=>x.id==='W37.07');
const failures=[], owned=new Set(b.owned.map(x=>x.path)), maps=new Map(), deltas=[];
for(const p of a.files) if(hash(fs.readFileSync(p.path))!==p.sha256)failures.push('pin:'+p.path);
for(const p of f.pins) if(!a.files.some(x=>x.path===p.path&&x.sha256===p.sha256))failures.push('freeze:'+p.path);
for(const p of b.pins) if(!owned.has(p.path)&&hash(fs.readFileSync(p.path))!==p.sha256)failures.push('unowned:'+p.path);
for(const d of w.delta_validation){
 const before=unzip(b.owned.find(x=>x.path===d.path).content_gzip_base64), after=fs.readFileSync(d.path,'utf8'),patch=unzip(d.diff_gzip_base64);
 const ok=hash(before)===d.admission_sha256&&hash(after)===d.current_sha256&&hash(patch)===d.diff_sha256&&diff.applyPatch(before,patch)===after&&diff.applyPatch(after,diff.reversePatch(diff.parsePatch(patch)[0]))===before;
 if(!ok)failures.push('delta:'+d.path);deltas.push({path:d.path,admission_sha256:hash(before),current_sha256:hash(after),diff_sha256:hash(patch),roundtrip:ok});
 let oldLine=1,newLine=1;const mapping=new Map();for(const part of diff.diffLines(before,after)){if(!part.added&&!part.removed)for(let i=0;i<part.count;i++)mapping.set(newLine+i,oldLine+i);if(!part.added)oldLine+=part.count;if(!part.removed)newLine+=part.count;}maps.set(d.path,mapping);
}
const lint=w.commands.find(x=>x.name==='lint'),lintText=unzip(lint.stdout_gzip_base64),lintRows=JSON.parse(lintText),lineage=JSON.parse(unzip(w.warning_lineage.lines_gzip_base64));
if(hash(lintText)!==lint.stdout_sha256)failures.push('lint-stdout');
let warnings=0,errors=0;for(const row of lintRows){const path=row.filePath.replace(process.cwd()+'/','');errors+=row.errorCount;for(const m of row.messages){warnings++;const old=maps.get(path)?.get(m.line);if(!old||!lineage.some(x=>x.path===path&&x.line===m.line&&x.column===m.column&&x.ruleId===m.ruleId&&x.message===m.message&&x.admission_line===old&&x.unchanged))failures.push('warning-lineage:'+path+':'+m.line);}}
const references=[dir+'evidence/W37.07/artifact.json',dir+'evidence/W37.07/worker.json',dir+'evidence/W37.07/source-freeze.json',dir+'design/W37.07/plan-v2.md',dir+'design/W37.07/baseline-v2.json','docs/architecture/35-audit-verification-and-source-of-truth.md'].map(path=>({path,sha256:hash(fs.readFileSync(path))}));
console.log(JSON.stringify({at:new Date().toISOString(),official_pins:a.files.length,source_pins:f.pins.length,unowned_pins:b.pins.length-b.owned.length,digest:a.digest,digest_matches:artifactDigest(a)===a.digest,tracker_artifact_matches:JSON.stringify(a)===JSON.stringify(t.artifact),contract_matches:a.contract_digest===t.preflight.contract_digest,retained_deltas:deltas,primary_outputs:w.commands.map(c=>({name:c.name,command:c.command,exit_code:c.exit_code,output_complete:c.output_complete,output_sha256:typeof c.output==='string'?hash(c.output):c.stdout_sha256})),lint:{warnings,errors,stderr:lint.stderr,lineage_count:lineage.length,stdout_sha256:hash(lintText)},references,failures},null,2));
